using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FinishWide {
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));const string Root="Assets/Afrer_Seconds/";
 public static object Metadata(){string p=Root+"06.Data/AssetSources/B345_TunnelDome_20261106.json";AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport);return new{scene=SceneManager.GetActiveScene().path,dirty=SceneManager.GetActiveScene().isDirty,playing=EditorApplication.isPlaying,metadata=AssetDatabase.LoadAssetAtPath<TextAsset>(p)!=null,guid=AssetDatabase.AssetPathToGUID(p)};}
 public static object CleanB4Lights(){if(EditorApplication.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit scene required");string original=SceneManager.GetActiveScene().path;var s=EditorSceneManager.OpenScene(Root+"01.Scenes/Stage/Level_B4_Stealth.unity");var names=new[]{"Ceiling_A","Ceiling_AN","Ceiling_AS","Ceiling_B","Ceiling_D"};var ls=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Light>()).Where(l=>l.enabled&&names.Contains(l.name)).ToArray();foreach(var l in ls){l.enabled=false;EditorUtility.SetDirty(l);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);EditorSceneManager.OpenScene(original);File.WriteAllText(Repo+"/Docs/검수/2026-11-06_B345_WideInterior/lighting_refine.json",JsonConvert.SerializeObject(new{floor="B4",additionalLegacyDomeLightsDisabled=ls.Length},Formatting.Indented));return ls.Length;}
 public static object PrepareReflections(){if(EditorApplication.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit scene required");string original=SceneManager.GetActiveScene().path;var layout=JObject.Parse(File.ReadAllText(Repo+"/Docs/도면/잠입_탐색/layout.json"));var report=new List<object>();try{foreach(string f in new[]{"B5","B4","B3"}){var s=EditorSceneManager.OpenScene(Root+"01.Scenes/Stage/Level_"+f+"_Stealth.unity");var rooms=layout["floors"].Single(p=>(string)p["floor"]==f)["rooms"];int n=0;foreach(var p in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ReflectionProbe>())){var c=p.transform.position+p.center;float u=c.x+24,v=c.z+16;var room=rooms.FirstOrDefault(r=>(string)r["roof"]?["kind"]=="dome"&&u>(float)r["x"]&&u<(float)r["x"]+(float)r["w"]&&v>(float)r["y"]&&v<(float)r["y"]+(float)r["h"]);if(room==null)continue;float h=(float)room["roof"]["crown"];p.size=new Vector3(p.size.x,h+.6f,p.size.z);p.center=new Vector3(p.center.x,(h-.2f)*.5f-p.transform.position.y,p.center.z);n++;}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);report.Add(new{floor=f,resizedDomeProbes=n});}}finally{EditorSceneManager.OpenScene(original);}return report;}
 public static object ImportCheck(){var logs=new List<string>();Application.LogCallback cb=(m,s,t)=>{if(t==LogType.Warning||t==LogType.Error||t==LogType.Exception)logs.Add(m);};Application.logMessageReceived+=cb;try{foreach(string f in new[]{"B5","B4","B3"})foreach(string n in new[]{"WC_"+f+"_Architecture","WC_"+f+"_Walls","WA_"+f+"_Interior"})AssetDatabase.ImportAsset(Root+"05.Model/Environment/"+f+"/"+n+".fbx",ImportAssetOptions.ForceUpdate|ImportAssetOptions.ForceSynchronousImport);}finally{Application.logMessageReceived-=cb;}File.WriteAllText(Repo+"/Docs/검수/2026-11-06_B345_WideInterior/import.json",JsonConvert.SerializeObject(new{logs},Formatting.Indented));return logs;}
}
